1	//! Tests for Innistrad werewolf double-faced cards.
2	
3	mod common;
4	
5	use common::*;
6	use mtg_engine::actions::{Action, Target};
7	use mtg_engine::cards::CardRegistry;
8	use mtg_engine::engine;
9	use mtg_engine::events::GameEvent;
10	use mtg_engine::sba::check_state_based_actions_with_registry;
11	use mtg_engine::triggers;
12	use mtg_engine::types::*;
13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	/// Helper: set up a werewolf on the battlefield and trigger its upkeep transform.
19	/// Returns the state after triggering the upkeep.
20	fn trigger_upkeep(state: &mut mtg_engine::state::GameState, registry: &CardRegistry) {
21	    state.events.push(GameEvent::StepStarted { step: Step::Upkeep });
22	    triggers::process_triggers(state, registry);
23	}
24	
25	// ── Reckless Waif ─────────────────────────────────────────────────
26	
27	#[test]
28	fn reckless_waif_transforms_when_no_spells_cast() {
29	    let reg = registry();
30	    let mut state = game_at_step(Step::Upkeep, P0);
31	    // spells_cast_last_turn is empty (no spells cast), is_first_turn is false
32	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
33	
34	    assert_eq!(state.effective_power(waif, &reg).unwrap(), 1);
35	    assert_eq!(state.effective_toughness(waif, &reg).unwrap(), 1);
36	
37	    trigger_upkeep(&mut state, &reg);
38	
39	    // Should be transformed to Merciless Predator 3/2
40	    let obj = state.get_object(waif).unwrap();
41	    assert!(obj.is_transformed, "Reckless Waif should transform when no spells cast last turn");
42	    assert_eq!(obj.name, "Merciless Predator");
43	    assert_eq!(state.effective_power(waif, &reg).unwrap(), 3);
44	    assert_eq!(state.effective_toughness(waif, &reg).unwrap(), 2);
45	}
46	
47	#[test]
48	fn reckless_waif_stays_human_on_first_turn() {
49	    let reg = registry();
50	    let mut state = game_at_step(Step::Upkeep, P0);
51	    state.is_first_turn = true;
52	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
53	
54	    trigger_upkeep(&mut state, &reg);
55	
56	    let obj = state.get_object(waif).unwrap();
57	    assert!(!obj.is_transformed, "Should not transform on first turn");
58	}
59	
60	#[test]
61	fn reckless_waif_stays_human_when_spells_cast() {
62	    let reg = registry();
63	    let mut state = game_at_step(Step::Upkeep, P0);
64	    state.spells_cast_last_turn.insert(P0, 1);
65	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
66	
67	    trigger_upkeep(&mut state, &reg);
68	
69	    let obj = state.get_object(waif).unwrap();
70	    assert!(!obj.is_transformed, "Should not transform when spells were cast");
71	}
72	
73	#[test]
74	fn reckless_waif_transforms_back_when_two_spells_cast() {
75	    let reg = registry();
76	    let mut state = game_at_step(Step::Upkeep, P0);
77	    let waif = named_creature(&mut state, &reg, "Reckless Waif", P0);
78	
79	    // Manually transform to werewolf side
80	    state.get_object_mut(waif).unwrap().is_transformed = true;
81	    state.get_object_mut(waif).unwrap().name = "Merciless Predator".into();
82	
83	    // Set up: a player cast 2 spells last turn
84	    state.spells_cast_last_turn.insert(P0, 2);
85	
86	    trigger_upkeep(&mut state, &reg);
87	
88	    let obj = state.get_object(waif).unwrap();
89	    assert!(!obj.is_transformed, "Should transform back when 2+ spells cast");
90	    assert_eq!(obj.name, "Reckless Waif");
91	    assert_eq!(state.effective_power(waif, &reg).unwrap(), 1);
92	}
93	
94	// ── Gatstaf Shepherd ──────────────────────────────────────────────
95	
96	#[test]
97	fn gatstaf_shepherd_transforms_and_gains_intimidate() {
98	    let reg = registry();
99	    let mut state = game_at_step(Step::Upkeep, P0);
100	    let shepherd = named_creature(&mut state, &reg, "Gatstaf Shepherd", P0);
101	
102	    trigger_upkeep(&mut state, &reg);
103	
104	    let obj = state.get_object(shepherd).unwrap();
105	    assert!(obj.is_transformed);
106	    assert_eq!(obj.name, "Gatstaf Howler");
107	    assert_eq!(state.effective_power(shepherd, &reg).unwrap(), 3);
108	    assert_eq!(state.effective_toughness(shepherd, &reg).unwrap(), 3);
109	    assert!(state.has_keyword(shepherd, Keyword::Intimidate, &reg),
110	        "Gatstaf Howler should have Intimidate");
111	}
112	
113	#[test]
114	fn gatstaf_shepherd_loses_intimidate_on_transform_back() {
